import test from 'node:test';
import assert from 'node:assert/strict';
import { createInvoice, issueInvoice, invoiceTotals } from '../src/invoices.js';
import { recordPayment, balanceDue } from '../src/payments.js';
import { exportCsv } from '../src/export.js';

test('exportCsv returns string with header', () => {
  const result = exportCsv([]);
  assert(typeof result === 'string');
  assert(result.includes('number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due'));
});

test('exportCsv header is first line', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
});

test('exportCsv empty invoices list', () => {
  const result = exportCsv([]);
  const lines = result.split('\n');
  assert.equal(lines.length, 2);
  assert.equal(lines[1], '');
});

test('exportCsv single issued invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert(lines[1].includes(issued.value.number));
  assert(lines[1].includes('2026-10-07'));
  assert(lines[1].includes('issued'));
});

test('exportCsv multiple invoices', () => {
  const inv1 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = exportCsv([issued1.value, issued2.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 4);
  assert(lines[1].includes(issued1.value.number));
  assert(lines[2].includes(issued2.value.number));
});

test('exportCsv includes customer name', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(result.includes('Alice Johnson'));
});

test('exportCsv formats amounts in euros', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);

  const euros = (totals.subtotal / 100).toFixed(2);
  assert(result.includes(euros));
});

test('exportCsv amounts have 2 decimal places', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const subtotal = fields[5];
  assert(subtotal.includes('.'));
  const decimals = subtotal.split('.')[1];
  assert.equal(decimals.length, 2);
});

test('exportCsv includes due amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const due = balanceDue(issued.value);

  const result = exportCsv([issued.value]);

  const dueEuros = (due / 100).toFixed(2);
  assert(result.includes(dueEuros));
});

test('exportCsv due is 0 for paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });

  const result = exportCsv([paid.value]);

  assert(result.includes('0.00'));
});

test('exportCsv draft invoice status', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const result = exportCsv([inv.value]);

  assert(result.includes('draft'));
});

test('exportCsv escapes customer name with comma', () => {
  const inv = createInvoice({
    customerId: 'C-004',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(result.includes('"'));
});

test('exportCsv escapes customer name with double quote', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  const lines = result.split('\n');
  assert(lines[1].includes('"'));
});

test('exportCsv double-escapes quotes in customer name', () => {
  const inv = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(result.includes('""'));
});

test('exportCsv includes all fields in correct order', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  assert.equal(fields.length, 10);
  assert(fields[0].includes(issued.value.number));
  assert(fields[2] === '2026-10-07');
  assert(fields[4] === 'issued');
});

test('exportCsv with discount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const discount = parseFloat(fields[6]);
  assert(discount > 0);
  assert.equal(discount, totals.discount / 100);
});

test('exportCsv with VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const vat = parseFloat(fields[7]);
  assert(vat > 0);
  assert.equal(vat, totals.vat / 100);
});

test('exportCsv partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const half = Math.floor(totals.total / 2);
  const partial = recordPayment(issued.value, { amount: half, date: '2026-10-08' });

  const result = exportCsv([partial.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const due = parseFloat(fields[9]);
  assert(due > 0);
  assert(due < totals.total / 100);
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];
  for (let i = 0; i < 5; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-10-0${i + 1}`,
      lines: [{ sku: 'DES-HOUR', qty: i + 1 }],
    });
    const issued = issueInvoice(inv.value, invoices.length > 0 ? [`INV-${invoices.length}`] : []);
    invoices.push(issued.value);
  }

  const result = exportCsv(invoices);
  const lines = result.split('\n');

  for (let i = 0; i < invoices.length; i++) {
    assert(lines[i + 1].includes(invoices[i].number));
  }
});

test('exportCsv lines end with newline', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(result.endsWith('\n'));
});

test('exportCsv single line ends with newline', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert(lines[1].endsWith(''));
  assert(result.includes(issued.value.number + '\n') || !result.endsWith('\n') || result.includes('\n'));
});

test('exportCsv all invoice statuses', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const paid = recordPayment(issued.value, { amount: totals.total, date: '2026-10-08' });

  const result = exportCsv([inv.value, issued.value, paid.value]);

  assert(result.includes('draft'));
  assert(result.includes('issued'));
  assert(result.includes('paid'));
});

test('exportCsv with multiple lines per invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DES-HOUR', qty: 1 },
      { sku: 'DES-HOUR', qty: 2 },
      { sku: 'BRAND-BOOK', qty: 1 },
    ],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');

  assert.equal(lines.length, 3);
  assert(lines[1].includes(issued.value.number));
});

test('exportCsv amount formats with dot separator', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 10 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(result.includes('.'));
  assert(!result.includes(',0') && !result.includes(',1') && !result.includes(',2'));
});

test('exportCsv large due amount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(result.includes(issued.value.number));
  assert(result.includes('issued'));
});

test('exportCsv no thousands separator', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'BRAND-BOOK', qty: 100 }],
  });
  const issued = issueInvoice(inv.value, []);

  const result = exportCsv([issued.value]);

  assert(!result.includes('1,'));
  assert(!result.includes('10,'));
});

test('exportCsv customer name not found fallback', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const brokenInvoice = { ...issued.value, customerId: 'UNKNOWN-CUSTOMER' };

  const result = exportCsv([brokenInvoice]);

  assert(result.includes('UNKNOWN-CUSTOMER'));
});

test('exportCsv different customers', () => {
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });

  const issued1 = issueInvoice(inv1.value, []);
  const issued2 = issueInvoice(inv2.value, ['INV-001']);

  const result = exportCsv([issued1.value, issued2.value]);

  assert(result.includes('Bob Smith'));
  assert(result.includes('Alice Johnson'));
});

