  const due = balanceDue(issued.value);

  const result = exportCsv([issued.value]);

  const dueEuros = (due / 100).toFixed(2);
  assert(result.includes(dueEuros));
});

test('exportCsv due is 0 for paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
