test('exportCsv with discount', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1, discountPercent: 10 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const discount = parseFloat(fields[6]);
  assert(discount > 0);
  assert.equal(discount, totals.discount / 100);
});

test('exportCsv with VAT', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);

  const result = exportCsv([issued.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const vat = parseFloat(fields[7]);
  assert(vat > 0);
  assert.equal(vat, totals.vat / 100);
});

test('exportCsv partially paid invoice', () => {
  const inv = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(inv.value, []);
  const totals = invoiceTotals(issued.value);
  const half = Math.floor(totals.total / 2);
  const partial = recordPayment(issued.value, { amount: half, date: '2026-10-08' });

  const result = exportCsv([partial.value]);
  const lines = result.split('\n');
  const fields = lines[1].split(',');

  const due = parseFloat(fields[9]);
  assert(due > 0);
  assert(due < totals.total / 100);
});

test('exportCsv preserves invoice order', () => {
  const invoices = [];
  for (let i = 0; i < 5; i++) {
    const inv = createInvoice({
      customerId: 'C-002',
      issueDate: `2026-10-0${i + 1}`,
      lines: [{ sku: 'DES-HOUR', qty: i + 1 }],
    });
    const issued = issueInvoice(inv.value, invoices.length > 0 ? [`INV-${invoices.length}`] : []);
    invoices.push(issued.value);
  }

  const result = exportCsv(invoices);
  const lines = result.split('\n');

  for (let i = 0; i < invoices.length; i++) {
    assert(lines[i + 1].includes(invoices[i].number));
  }
});

test('exportCsv lines end with newline', () => {
